#include <bits/stdc++.h>
using namespace std;

// Union-Find
template <class Type>
class UnionFindW
{
public:
    UnionFindW() = default;

    /// @brief Union-Find 木を構築します。
    /// @param n 要素数
    explicit UnionFindW(size_t n)
        : param(n, -1), diff_w(n) {};

    /// @brief 頂点 i の root のインデックスを返します。
    /// @param i 調べる頂点のインデックス
    /// @return 頂点 i の root のインデックス
    int root(int i)
    {
        const int y = param.at(i);
        if (y < 0)
        {
            return i;
        }

        const int x = root(y);
        diff_w.at(i) += diff_w.at(y);

        // 経路圧縮
        return (param.at(i) = x);
    }

    /// @brief a のグループと b のグループを統合します。
    /// @param a 一方のインデックス
    /// @param b 他方のインデックス
    /// @param w (bの重み) - (aの重み)
    void unite(int a, int b, Type w)
    {

        w = w + weight(a) - weight(b);

        a = root(a);
        b = root(b);       

        if (a != b)
        {
            // union by size (小さいほうが子になる）
            if (-param.at(a) < -param.at(b))
            {
                std::swap(a, b);
                w = -w;
            }

            param.at(a) += param.at(b);
            param.at(b) = a;
            diff_w.at(b) = w;
        }
    }

    /// @brief a と b が同じグループに属すかを返します。
    /// @param a 一方のインデックス
    /// @param b 他方のインデックス
    /// @return a と b が同じグループに属す場合 true, それ以外の場合は false
    bool issame(int a, int b)
    {
        return (root(a) == root(b));
    }

    /// @brief i が属するグループの要素数を返します。
    /// @param i インデックス
    /// @return i が属するグループの要素数
    int size(int i)
    {
        return -param.at(root(i));
    }

    /// @brief (b の重み) - (a の重み) を返します。
    /// @param a 一方のインデックス
    /// @param b 他方のインデックス
    /// @remark a と b が同じグループに属さない場合の結果は不定です。
    /// @return (b の重み) - (a の重み)
    Type diff(int a, int b)
    {
        return (weight(b) - weight(a));
    }

private:
    // param[i] は i の 親,
    // ただし root の場合は (-1 * そのグループに属する要素数)
    std::vector<int> param;

    std::vector<Type> diff_w;

    Type weight(int i)
    {
        root(i);
        return diff_w.at(i);
    }
};

int main(void)
{
    int n, m;
    cin >> n >> m;
    UnionFindW<int> uf(n);
    for (int i = 0; i < m; i++)
    {
        int l, r, d;
        cin >> l >> r >> d;
        l--;
        r--;
        if (uf.issame(l, r))
        {
            if (uf.diff(l, r) != d)
            {
                cout << "No" << endl;
                return 0;
            }
        }
        else
        {
            uf.unite(l, r, d);
        }
    }
    cout << "Yes" << endl;
    return 0;
}

